import{u as e,w as t}from"./console-core-CEPREpW1.js";import{x as n}from"./console-icons-np31iUGZ.js";var r=e(`beaker`,[[`path`,{d:`M4.5 3h15`,key:`c7n0jr`}],[`path`,{d:`M6 3v16a2 2 0 0 0 2 2h8a2 2 0 0 0 2-2V3`,key:`m1uhx7`}],[`path`,{d:`M6 14h12`,key:`4cwo0f`}]]),i=e(`compass`,[[`circle`,{cx:`12`,cy:`12`,r:`10`,key:`1mglay`}],[`path`,{d:`m16.24 7.76-1.804 5.411a2 2 0 0 1-1.265 1.265L7.76 16.24l1.804-5.411a2 2 0 0 1 1.265-1.265z`,key:`9ktpf1`}]]),a=e(`shield-alert`,[[`path`,{d:`M20 13c0 5-3.5 7.5-7.66 8.95a1 1 0 0 1-.67-.01C7.5 20.5 4 18 4 13V6a1 1 0 0 1 1-1c2 0 4.5-1.2 6.24-2.72a1.17 1.17 0 0 1 1.52 0C14.51 3.81 17 5 19 5a1 1 0 0 1 1 1z`,key:`oel41y`}],[`path`,{d:`M12 8v4`,key:`1got3b`}],[`path`,{d:`M12 16h.01`,key:`1drbdi`}]]),o=t(),s=[{state:`Available in this build`,slug:`available`,icon:n,items:[[`Workbench + themes`,`Local workbench, paired themes, and recent bounded discoveries.`],[`Host port scanner`,`Custom TCP ports and ranges for one local or remote host, IPv4/IPv6, presets, cancellation, open/closed/timeout evidence, and protocol inspection handoffs.`],[`WebSocket + SSE`,`Text/binary WebSocket messages, SSE event names and IDs, headers, verified TLS, bounded live timelines, explicit connect/disconnect, and cleanup on navigation.`],[`gRPC workbench`,`Reflection, proto/protoset schemas, all stream modes, deadlines, headers, messages, trailers, and status.`],[`Cap’n Proto RPC`,`Source or compiled schemas, concrete bootstrap methods, exact 64-bit JSON values, verified TLS, deadlines, cancellation and response export. Source compilation uses an optional installed compiler.`],[`HTTP workbench`,`Bounded HTTP(S), verified TLS, explicit redirects, peer, timing, headers, response bodies, and bounded credential-redacted cURL export.`],[`Saved HTTP requests`,`Named browser-local requests with explicit body opt-in, update/delete/export, bounded storage, credential removal and global fuzzy search. Loading prepares an unsent editor.`],[`Bounded discovery`,`Explicit TCP, gRPC, TLS, and HTTP evidence with fixed candidate and time limits.`],[`Next-hop evidence`,`One read-only kernel route lookup per resolved address from the ProtoPeek process; no hop probes.`],[`Network Path · Linux + Windows`,`Native Linux UDP and Windows IPv4/IPv6 ICMP probes, pinned destinations, per-responder RTT, saved traces and optional dated ASN/ISP/location labels.`],[`Authorized private discovery`,`Explicit RFC 1918 IPv4 /24-or-smaller discovery with a previewed plan: bounded gRPC/HTTP inspection only on named application ports, TCP connect-only evidence elsewhere, hard limits, and cancellation.`],[`Network map + history`,`Responsive topology and accessible inventory views, manual subnet/site/VLAN/region groups, immutable snapshots, tags and notes, bounded browser persistence, and JSON/GraphML/CSV exchange.`],[`Offline Nmap XML import`,`Bounded hints from an existing nmap -oX file. Nmap is not required for import; literal-IP endpoints are verified before opening a workbench.`],[`Installed Nmap scanner`,`Explicit TCP connect or light service detection on one IP or a bounded private subnet, exact scope preview, cancellation, paginated results, export and protocol inspection handoff. Nmap is installed separately.`],[`Packet inspection`,`Bounded PCAP/PCAPNG metadata, paginated packet details, filters and JSON export. An installed dumpcap adapter supports explicit timed IP/port capture; native capture platform acceptance is still pending.`],[`Tailscale client workbench`,`Installed-client peers, accounts, exit-node controls, bounded diagnostics and Taildrop, with explicit reviewed operations. Integrated sign-in, elevation, Headscale administration and NetBird remain open work.`],[`Browser proto folders`,`Review and upload a bounded relative-path .proto manifest to the running ProtoPeek instance; folder access and schema bytes are never saved in profiles.`],[`gRPC Health Check + Watch`,`Explicit canonical checks and one bounded live Watch with status transitions, headers, trailers, cancellation, and final gRPC evidence; no polling or retry.`],[`Downloader`,`HTTP(S) queues through configured, system or bundled Windows amd64 aria2c, bounded options, live progress, pause/resume, restart recovery, completed history, checksum evidence and one-shot CLI transfer.`],[`Security evidence`,`Public website HEAD/TLS evidence and JSON reports, a fixed five-path metadata plan, historical indexed names with filtering/export and unsent Inspect handoffs. No security score or automatic candidate probing.`],[`GoBarryGo bridge`,`Read-first preview, bounded copy-only preference/session import, paused imported jobs, private receipts, and guarded rollback without changing GoBarryGo source files.`],[`Cloudflare Tunnels · local foundation`,`Manual, read-only discovery of cloudflared, its canonical OS service, documented config candidates, config authority, ingress routes, and Docker and Wrangler availability, plus safe in-view route drafts.`],[`Owned package channels`,`Homebrew on macOS/Linux and Scoop on Windows install checksum-pinned v0.5.0 archives, declare aria2 as an external dependency, and provide both protopeek and pp.`]]},{state:`Next`,slug:`next`,icon:i,items:[[`Incremental response-lab streams`,`Render each general server-stream message immediately with bounded retention while keeping headers, trailers, cancellation, and final status distinct.`],[`HTTP environment profiles + library import`,`Environment variables and portable library restoration beyond the current named request save/load/export workflow.`],[`cURL import`,`Parse a deliberately bounded cURL subset without silently accepting unsafe shell behavior; export is available now.`],[`Target DNS + TLS preflight`,`Explain resolution, SNI, ALPN, certificate verification, and handshake timing before an RPC or HTTP request.`],[`Darwin path backend`,`Earn native unprivileged implementations with equivalent cancellation and evidence semantics; no localized subprocess parsing or elevation prompts.`],[`Snapshot diff + sourced enrichment`,`Compare immutable observations over time. Current traces already retain optional sourced ASN/ISP/location labels; IP location does not establish a datacenter.`],[`WinGet package`,`Prepare and owner-submit a schema-valid Windows package only after the owned Scoop path and installer have initial user feedback.`],[`Tunnel validation + runtime evidence`,`Add authoritative cloudflared validation, route matching, bounded logs, metrics, and diagnostics without ambient polling or credential reads.`]]},{state:`Exploring`,slug:`exploring`,icon:r,items:[[`Nmap XML to topology`,`Map bounded existing XML hints into a saved workspace with import provenance and explicit loss notices, without executing Nmap.`],[`Cap’n Proto capability workflows`,`Follow returned capabilities, generic bindings and pipelined calls beyond the current concrete bootstrap method client.`],[`QUIC + HTTP/3`,`Negotiation and transport evidence once a compact, reliable cross-platform path is proven.`]]},{state:`Gated`,slug:`gated`,icon:a,items:[[`Bundled Nmap execution`,`Not planned for the core binary. Reconsider only as an opt-in companion with explicit executable choice, previewed scope, hard budgets, and an auditable command.`],[`Broader/public range discovery`,`Why: one authorized private /24 must not become ambient or Internet-wide crawling. Gate: a distinct workflow, previewed scope, harder budgets, and a defensible user need.`],[`Automatic datacenter geolocation claims`,`Why: SIN, BOM, provider-region labels, WHOIS, and IP geolocation are hints rather than measured facilities. Gate: user-supplied sources, attribution, freshness, and confidence.`],[`Capture elevation and deeper decoding`,`The installed-tool adapter uses existing permissions. Driver installation, integrated elevation, stream reassembly, raw payload export and decryption need separate workflows.`],[`Tunnel service and config mutation`,`Why: host service control, credential paths, and config writes cross a privilege boundary. Gate: deliberate elevation, least-privilege helpers, atomic writes, validation, rollback, and auditable receipts.`]]}];function c(){return(0,o.jsxs)(`div`,{className:`pp-evidence-workbench pp-roadmap-page`,children:[(0,o.jsx)(`header`,{className:`pp-evidence-hero`,children:(0,o.jsxs)(`div`,{children:[(0,o.jsx)(`span`,{className:`pp-kicker`,children:`Capability contract`}),(0,o.jsx)(`h1`,{children:`Product roadmap`}),(0,o.jsx)(`p`,{children:`What works now, what closes daily workflow gaps next, and what needs a safety gate.`})]})}),(0,o.jsx)(`div`,{className:`pp-roadmap-grid`,children:s.map(e=>(0,o.jsxs)(`section`,{className:`pp-roadmap-group is-${e.slug}`,children:[(0,o.jsxs)(`header`,{children:[(0,o.jsx)(e.icon,{"aria-hidden":`true`}),(0,o.jsx)(`h2`,{children:e.state}),(0,o.jsx)(`span`,{children:e.items.length})]}),(0,o.jsx)(`div`,{children:e.items.map(([e,t])=>(0,o.jsxs)(`article`,{children:[(0,o.jsx)(`h3`,{children:e}),(0,o.jsx)(`p`,{children:t})]},e))})]},e.state))})]})}export{c as Roadmap};